function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof UDHWA_INFO&&(n.innerHTML=UDHWA_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderEcology(){if("undefined"==typeof ECOLOGY_HYDROLOGY)return;const n=document.getElementById("eco-overview"),e=document.getElementById("eco-lakes"),t=document.getElementById("eco-biodiversity"),s=document.getElementById("eco-status");n&&(n.innerHTML=`<strong>Overview:</strong> ${ECOLOGY_HYDROLOGY.overview}`),e&&(e.innerHTML=`<strong>Twin Oxbow Lakes Hydrology (Patauda & Berhale):</strong> ${ECOLOGY_HYDROLOGY.lakesHydrology}`),t&&(t.innerHTML=`<strong>Wetland Biodiversity:</strong> ${ECOLOGY_HYDROLOGY.biodiversity}`),s&&(s.innerHTML=`<strong>Conservation Status:</strong> ${ECOLOGY_HYDROLOGY.conservationStatus}`)}function renderSpecies(){const n=document.getElementById("species-grid");n&&"undefined"!=typeof BIRD_SPECIES&&(n.innerHTML=BIRD_SPECIES.map(n=>`\n        <div class="species-card">\n            <img src="${n.image}" alt="${n.name}" loading="lazy" />\n            <div class="species-card-body">\n                <div class="species-header">\n                    <h3>${n.name} ${n.icon}</h3>\n                    <span class="status-badge">${n.status}</span>\n                </div>\n                <p class="scientific-name"><em>${n.scientificName}</em></p>\n                <p>${n.description}</p>\n                <div class="bird-meta">\n                    <span>🗓️ ${n.season}</span> | \n                    <span>🪶 Wingspan: ${n.wingspan}</span>\n                </div>\n            </div>\n        </div>\n    `).join(""))}function renderHotspots(){const n=document.getElementById("hotspots-grid");n&&"undefined"!=typeof MAP_HOTSPOTS&&(n.innerHTML=MAP_HOTSPOTS.map(n=>`\n        <div class="hotspot-card">\n            <h3>📍 ${n.title}</h3>\n            <span class="spot-type">${n.type}</span>\n            <p>${n.description}</p>\n            <small>Coordinates: ${n.lat}° N, ${n.lng}° E</small>\n        </div>\n    `).join(""))}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderEcology(),renderSpecies(),renderHotspots(),renderGallery(),initThemeToggle()});